package harbor.client

import harbor.client.generated.marketdata.PricesApi
import harbor.client.generated.marketdata.model.PriceCurve
import harbor.enums.ProductGroup
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component
import org.springframework.web.client.RestClient
import java.math.BigDecimal
import java.time.Instant
import java.time.YearMonth

/**
 * Thin wrapper around the market-data service (baseline price and transport price curves).
 *
 * `PricesApi` and `PriceCurve` are generated by openapi-generator from `api/market-data.yaml`
 * into package `harbor.client.generated.marketdata` (not committed).
 */
@Component
class MarketDataClient(
    restClientBuilder: RestClient.Builder,
    @Value("\${harbor.external.market-data.base-url}") baseUrl: String,
) {
    private val api = PricesApi(restClientBuilder.baseUrl(baseUrl).build())

    data class Curve(val asOf: Instant, val points: Map<YearMonth, BigDecimal>)

    fun prices(productGroup: ProductGroup, from: YearMonth, to: YearMonth): Curve =
        api.getPrices(
            productGroup = productGroup.wireValue,
            corridor = productGroup.corridor,
            from = from.toString(),
            to = to.toString(),
        ).toCurve()

    fun transportPrices(productGroup: ProductGroup): Curve =
        api.getTransportPrices(productGroup = productGroup.wireValue, corridor = productGroup.corridor).toCurve()

    private fun PriceCurve.toCurve() = Curve(
        asOf = asOf.toInstant(),
        points = points.associate { YearMonth.parse(it.period) to it.price },
    )
}
